from knowledge_store import load_symbols,save_review
from printing_knowledge_continuation import A,record,checkpoint

def emit(path,details):
 out=[]
 for s in load_symbols(path)['symbols']:
  if not s['isCallable']:continue
  reason,ins,outs,side,issues,rels=details[s['startLine']]
  out.append(record(s,reason,ins,outs,side,'Station HTTP/filesystem/configuration and hardware acceptance are distinct trust boundaries; see individual reasoning','No direct SQL in PrintAgent; HTTP reporting/authentication may write server records if actually invoked','No physical verification performed; queuing, transport acceptance and paper completion must remain distinct','Sequential processing except explicitly described loops/HTTP waits; disk cost and retry limits reasoned individually','Physical retry identity and HTTP report idempotency are distinct; no cross-machine lease',issues,'Isolated fake transport/server or owned temp-file tests; no real auth/DB/printer actions. Specific missing cases stated in reasoning',rels))
 assert len(out)==len(details),(path,len(out),len(details))
 save_review(A,path,{'scope':'Every listed callable individually source-reasoned; interface declarations reviewed as contracts, not implementations','symbols':out})
 checkpoint(path+' '+str(len(out))+' individual callables','Continue remaining exact checkpoint IDs; preserve SEC001 matrix/harness separation')

